      applyStep1: 'PMEGP இ-போர்டல் (KVIC) மூலம் ஆன்லைனில் விண்ணப்பிக்கவும்.',
      applyStep2: 'மாவட்ட பணிக்குழு குழு விண்ணப்பத்தை ஆய்வு செய்து உங்கள் நிதி வங்கிக்கு அனுப்பும்.',
      applyStep3: 'வங்கி கடனை அனுமதிக்கும்; மானியம் 3 ஆண்டுகளுக்கு நிலையான வைப்பில் வைக்கப்பட்டு பின்னர் வரவு வைக்கப்படும்.',
