    validationTitle: 'உண்மையான முடிவுகளுக்கு எதிராக சரிபார்க்கப்பட்டது',
    validationBody: 'திட்ட பரிந்துரைகள் வரலாற்று கடன் மற்றும் கடன் முடிவு தரவுகளுக்கு எதிராக அளவீடு செய்யப்படுகின்றன, இது மாதிரியின் திட்ட வழிநடத்துதலுக்கும் உண்மையில் அங்கீகரிக்கப்பட்ட முடிவுகளுக்கும் இடையிலான கருத்து வேறுபாடு விகிதத்தை குறைவாகவும் தொடர்ந்து கண்காணிக்கப்படுவதாகவும் வைத்திருக்கிறது.',
    validationStat1: 'வரலாற்று ஒப்புதல்களுக்கு எதிரான கருத்து வேறுபாடு விகிதம்',
    validationStat2: 'ஒப்பிடப்பட்ட மாவட்ட தரவுத்தொகுப்புகள்',
    validationStat3: 'தேர்ச்சி பெற்ற திட்ட விதி சோதனை வழக்குகள்',
    dataGroundingTitle: 'இதை உண்மையான தரவில் நிலைநிறுத்துதல் — நேர்மையாக',
    dataGroundingBody: 'ஹைப்பர்-லோக்கல் கூற்றுகள் அவற்றின் அடியில் உள்ள தரவைப் போலவே நல்லவை. உண்மையில் என்ன நேரடியாக உள்ளது, எது காலமுறை, மற்றும் எது இன்னும் சிறந்த கிடைக்கக்கூடியது என்பது இங்கே — அதன் வரம்புகளுடன்.',
    dataVintageLive: 'நேரடி',
    dataVintagePeriodic: 'காலமுறை',
    dataVintageStatic: 'நிலையான',
    dataRowDigipin: { name: 'DIGIPIN (இந்தியா போஸ்ட்)', note: 'துல்லியமான 4மீ×4மீ புவிக்குறியீட்டு கட்டம் — இது ஒரு முகவரி-திறவுகோல், தரவுப் படுக்கை அல்ல' },
    dataRowCensus: { name: 'மக்கள்தொகை கணக்கெடுப்பு 2011 கிராம அடைவு', note: 'இன்றும் இந்தியாவின் மிகவும் விரிவான பொது-நோக்க கிராம தரவுத்தொகுப்பு — உண்மையில் 2011, அதன் பின் புதுப்பிக்கப்படவில்லை' },
    dataRowAntyodaya: { name: 'மிஷன் அந்த்யோதயா (கிராம பஞ்சாயத்து கணக்கெடுப்பு)', note: 'ஆண்டுதோறும், 21 துறை உள்கட்டமைப்பு குறியீடுகள் — கணக்கெடுப்பை விட புதியது, GP-அளவில்' },
    dataRowNrlm: { name: 'NRLM சுய உதவிக் குழு பதிவேடு', note: 'கிராம அளவில், தற்போதைய, சமூக வகை வாரியாக கட்டமைக்கப்பட்டது' },
    dataRowAgmarknet: { name: 'அக்மார்க்நெட் மண்டி விலைகள்', note: 'உண்மையில் நேரடி — தினசரி பொருள் விலை புதுப்பிப்புகள்' },
    dataRowAccountAggregator: { name: 'கணக்கு திரட்டி (சஹாமதி)', note: 'நேரடி, ஒப்புதல்-அடிப்படையிலானது — சுய-அறிவிக்கப்பட்ட புள்ளிவிவரங்களுக்குப் பதிலாக பயனரின் உண்மையான நிதித் தரவை சரிபார்க்கிறது' },
    roadmapTitle: 'சாலைவரைபடம் — உருவாக்கப்பட்டது vs அடுத்தது',
