    roadmapItemJanSamarth: 'ஜன் சமர்த் ஒருங்கிணைந்த கடன் போர்ட்டல் வழியாக நேரடி விண்ணப்ப சமர்ப்பணம்',
    roadmapItemWhatsapp: 'ஸ்மார்ட்போன் இல்லாத பயனர்களை அடையும் ஒரு வாட்ஸ்ஆப் / IVR சேனல்',
    roadmapItemAA: 'சரிபார்க்கப்பட்ட, ஒப்புதல்-அடிப்படையிலான நிதித் தரவுக்கான முழுமையான கணக்கு திரட்டி ஒருங்கிணைப்பு',
