  lessons: {
    sixtySecond: '60 வினாடி பாடம்',
    listen: 'கேளுங்கள்',
    stop: 'நிறுத்து',
    emiTitle: 'ஈஎம்ஐ என்றால் என்ன?',
    emiBody: 'ஈஎம்ஐ என்பது சம மாதத் தவணை — கடன் முழுவதும் தீரும் வரை ஒவ்வொரு மாதமும் செலுத்தும் ஒரே தொகை. இதில் எப்போதும் வட்டியுடன் கடனின் ஒரு பகுதியும் சேர்ந்திருக்கும், எனவே சில மாதங்களில் கூடுதலாகச் செலுத்துவதை விட, ஒவ்வொரு மாதமும் சரியான நேரத்தில் செலுத்துவது முக்கியம்.',
    moratoriumTitle: 'தவணை தள்ளுபடி காலம் என்றால் என்ன?',
    moratoriumBody: 'தவணை தள்ளுபடி காலம் என்பது உங்கள் ஈஎம்ஐ தொடங்குவதற்கு முந்தைய ஓய்வு காலம். இந்த நேரத்தில் வட்டி செலுத்த வேண்டும், ஆனால் கடன் தொகையை இன்னும் திருப்பிச் செலுத்த வேண்டியதில்லை — இது புதிய தொழிலுக்கு, பணம் திருப்பிச் செலுத்தத் தொடங்குவதற்கு முன், வருமானம் தொடங்குவதற்கான நேரத்தைத் தருகிறது.',
    marginTitle: 'மார்ஜின் தொகை என்றால் என்ன?',
    marginBody: 'மார்ஜின் என்பது திட்டச் செலவில் நீங்கள் உங்கள் சொந்த சேமிப்பிலிருந்து செலுத்தும் பகுதி — மீதமுள்ளது கடனாக வழங்கப்படும். அதிக மார்ஜின் பொதுவாக சிறிய கடனையும் குறைந்த ஈஎம்ஐயையும் குறிக்கும், எனவே முடிந்தால் விண்ணப்பிக்கும் முன் இன்னும் சிறிது சேமிப்பது நல்லது.',
  },
